import{_ as d,o as e,c as a,a3 as r}from"./chunks/framework.BlfGB29P.js";const b=JSON.parse('{"title":"架构设计模板","description":"以流式 AI 工作台为例，给出分层、组件职责、数据流与状态所有权均已填好的架构设计模板。","frontmatter":{"title":"架构设计模板","description":"以流式 AI 工作台为例，给出分层、组件职责、数据流与状态所有权均已填好的架构设计模板。","outline":[2,3],"article":{"type":"index","structure":"index"}},"headers":[],"relativePath":"ts-ai/appendix/templates/architecture-design-template.md","filePath":"ts-ai/appendix/templates/architecture-design-template.md","lastUpdated":1786166505000}'),s={name:"ts-ai/appendix/templates/architecture-design-template.md"};function n(i,t,h,o,c,l){return e(),a("div",null,[...t[0]||(t[0]=[r(`<h1 id="架构设计模板" tabindex="-1">架构设计模板 <a class="header-anchor" href="#架构设计模板" aria-label="Permalink to &quot;架构设计模板&quot;">​</a></h1><blockquote><p>作者：cursor-grok-4.5</p></blockquote><p>本模板用于把<strong>本项目</strong>的分层、组件、数据流与状态所有权写成可评审的一页（可附一图）。决策层模型见 <a href="/ts-ai/architecture/design-decisions/ts-ai-fullstack-architecture">TS-AI 全栈分层架构</a>、<a href="/ts-ai/architecture/design-decisions/framework-boundaries">框架边界</a>；物理目录见 <a href="/ts-ai/appendix/templates/project-directory-template">项目目录模板</a>。禁止只交空框图。</p><h2 id="_1-用途与何时使用" tabindex="-1">1. 用途与何时使用 <a class="header-anchor" href="#_1-用途与何时使用" aria-label="Permalink to &quot;1. 用途与何时使用&quot;">​</a></h2><h3 id="_1-1-用途" tabindex="-1">1.1 用途 <a class="header-anchor" href="#_1-1-用途" aria-label="Permalink to &quot;1.1 用途&quot;">​</a></h3><table tabindex="0"><thead><tr><th>用途</th><th>说明</th></tr></thead><tbody><tr><td>冻结依赖方向</td><td>交互 → 应用 → Agent → 数据 / 基础设施</td></tr><tr><td>标明组件职责与非职责</td><td>避免 Chat UI 兼做 Gateway</td></tr><tr><td>对齐交付契约</td><td>与需求、数据权限、威胁模型用同一系统边界</td></tr></tbody></table><h3 id="_1-2-何时使用" tabindex="-1">1.2 何时使用 <a class="header-anchor" href="#_1-2-何时使用" aria-label="Permalink to &quot;1.2 何时使用&quot;">​</a></h3><table tabindex="0"><thead><tr><th>时机</th><th>动作</th></tr></thead><tbody><tr><td>需求初稿后</td><td>填身份卡 + 上下文图</td></tr><tr><td>基线可跑前</td><td>补数据流与状态所有权</td></tr><tr><td>引入 RAG / 审批图前</td><td>增层或增组件，不改已冻结对外协议</td></tr><tr><td>威胁建模前</td><td>本模板的边界即信任边界输入</td></tr></tbody></table><p>下文示例项目：<strong>流式 AI 工作台</strong>（<code>stream-workbench-v1</code>）。知识库升级时在同一图上增加 Ingestion / Retrieval，不另起一套对外协议。</p><h2 id="_2-填写后的完整示例" tabindex="-1">2. 填写后的完整示例 <a class="header-anchor" href="#_2-填写后的完整示例" aria-label="Permalink to &quot;2. 填写后的完整示例&quot;">​</a></h2><h3 id="_2-1-文档身份-已填" tabindex="-1">2.1 文档身份（已填） <a class="header-anchor" href="#_2-1-文档身份-已填" aria-label="Permalink to &quot;2.1 文档身份（已填）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>填写值</th></tr></thead><tbody><tr><td>系统名称</td><td>流式 AI 工作台</td></tr><tr><td>文档版本</td><td><code>arch@1.4.0</code></td></tr><tr><td>对应候选</td><td><code>web@1.4.0</code> / <code>api@1.4.0</code> / <code>prompt-pack@2026-08-01</code></td></tr><tr><td>作者</td><td>工程赵衡</td></tr><tr><td>评审人</td><td>架构 + 安全陈安</td></tr><tr><td>关联交付</td><td><a href="/ts-ai/architecture/delivery/requirements-acceptance">需求与验收</a>、<a href="/ts-ai/architecture/delivery/threat-model">威胁模型</a></td></tr><tr><td>非目标</td><td>重 RAG、LangGraph 多级审批、WebSocket 双向会话（V1）</td></tr></tbody></table><h3 id="_2-2-上下文与信任边界-已填" tabindex="-1">2.2 上下文与信任边界（已填） <a class="header-anchor" href="#_2-2-上下文与信任边界-已填" aria-label="Permalink to &quot;2.2 上下文与信任边界（已填）&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[用户浏览器 / Nuxt Chat]</span></span>
<span class="line"><span>        |  HTTPS + Bearer；产品 SSE</span></span>
<span class="line"><span>        v</span></span>
<span class="line"><span>[Nest AI API] -----&gt; [Model Gateway] -----&gt; [模型供应商]</span></span>
<span class="line"><span>        |                    ^</span></span>
<span class="line"><span>        +---- PostgreSQL ----+</span></span>
<span class="line"><span>        |</span></span>
<span class="line"><span>        +---- Redis（限流 / confirm nonce）</span></span>
<span class="line"><span>        |</span></span>
<span class="line"><span>        +---- 工具适配器（可选只读查单；确认后执行）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p><strong>不信任</strong>：浏览器输入、客户端自报 <code>tenantId</code>、模型「已授权」话术、未校验工具参数。</p><h3 id="_2-3-分层落点-已填" tabindex="-1">2.3 分层落点（已填） <a class="header-anchor" href="#_2-3-分层落点-已填" aria-label="Permalink to &quot;2.3 分层落点（已填）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>本项目组件</th><th>职责</th><th>非职责</th></tr></thead><tbody><tr><td>交互</td><td><code>apps/web</code> Chat UI、<code>useAgentChat</code></td><td>流式渲染、停止、重连、确认卡投影</td><td>持有 Key；写 Thread 真相</td></tr><tr><td>应用</td><td>Nest modules: auth/threads/runs/sse</td><td>鉴权租户、协议适配、用例编排、幂等</td><td>直接拼供应商 SDK 散落各处</td></tr><tr><td>Agent</td><td><code>createAgent</code> 或等价编排（可空工具）</td><td>多轮消息、工具选择（若启用）</td><td>审批长流程；跨租户检索</td></tr><tr><td>工作流</td><td><strong>V1 不启用</strong></td><td>—</td><td>退款 Interrupt（留给售后）</td></tr><tr><td>数据</td><td>PG Thread/Run/Message</td><td>会话事实与 Run 生命周期</td><td>UI draft</td></tr><tr><td>基础设施</td><td>Gateway、Redis、日志/Trace</td><td>模型别名、限流、可观测</td><td>业务 ACL 规则（属应用/数据）</td></tr></tbody></table><h3 id="_2-4-关键用例数据流-已填" tabindex="-1">2.4 关键用例数据流（已填） <a class="header-anchor" href="#_2-4-关键用例数据流-已填" aria-label="Permalink to &quot;2.4 关键用例数据流（已填）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>步骤</th><th>组件</th><th>数据</th><th>备注</th></tr></thead><tbody><tr><td>1</td><td>Nuxt</td><td><code>POST /v1/threads/{id}/runs</code> + <code>Idempotency-Key</code></td><td>乐观 user 气泡可选</td></tr><tr><td>2</td><td>Nest runs</td><td>事务写 user Message + Run=<code>queued</code></td><td>tenant 来自 Token</td></tr><tr><td>3</td><td>Nest + Gateway</td><td>流式调用模型</td><td>Key 仅服务端</td></tr><tr><td>4</td><td>Nest sse</td><td><code>run.started</code> → <code>message.delta</code>* → <code>run.completed</code></td><td>单调 event id</td></tr><tr><td>5</td><td>Nuxt</td><td>投影气泡；刷新后 REST 拉历史再订 SSE</td><td>UI 临时态可丢</td></tr><tr><td>6</td><td>用户点停止</td><td><code>POST cancel</code> → AbortController</td><td>Run=<code>cancelled</code></td></tr></tbody></table><p>工具确认路径（可选）：模型提出工具 → API 发 <code>confirmation_required</code> → 用户确认 → 服务端校验 args hash → 执行 → 结果进 Message。</p><h3 id="_2-5-状态所有权摘要-已填" tabindex="-1">2.5 状态所有权摘要（已填） <a class="header-anchor" href="#_2-5-状态所有权摘要-已填" aria-label="Permalink to &quot;2.5 状态所有权摘要（已填）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>状态</th><th>权威</th><th>投影</th></tr></thead><tbody><tr><td>draft / connection</td><td>Nuxt</td><td>—</td></tr><tr><td>Thread / Message</td><td>Nest + PG</td><td>Nuxt 列表</td></tr><tr><td>Run.status</td><td>Nest + PG</td><td>按钮态、横幅</td></tr><tr><td>SSE 序号</td><td>Nest</td><td><code>Last-Event-ID</code></td></tr><tr><td>confirm nonce</td><td>Redis + Nest</td><td>确认卡</td></tr></tbody></table><p>完整矩阵见 <a href="/ts-ai/architecture/design-decisions/frontend-backend-state-ownership">前后端状态所有权</a>；目录注释见 <a href="/ts-ai/appendix/templates/project-directory-template">项目目录模板</a>。</p><h3 id="_2-6-质量属性与约束-已填" tabindex="-1">2.6 质量属性与约束（已填） <a class="header-anchor" href="#_2-6-质量属性与约束-已填" aria-label="Permalink to &quot;2.6 质量属性与约束（已填）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>目标（本项目）</th><th>验证</th></tr></thead><tbody><tr><td>首 Token 延迟</td><td>P95 ≤ 2.5s</td><td>预发压测 + 指标</td></tr><tr><td>取消正确性</td><td>停止后无继续 delta</td><td>e2e + 单元</td></tr><tr><td>租户隔离</td><td>跨租户 403/404</td><td><code>authz.e2e</code></td></tr><tr><td>可用性</td><td>供应商故障可失败可观测</td><td>Gateway 超时/回退策略</td></tr><tr><td>成本</td><td>单轮均价受网关记录</td><td>usage 日志</td></tr></tbody></table><h3 id="_2-7-升级对照-企业知识库助手-摘要已填" tabindex="-1">2.7 升级对照：企业知识库助手（摘要已填） <a class="header-anchor" href="#_2-7-升级对照-企业知识库助手-摘要已填" aria-label="Permalink to &quot;2.7 升级对照：企业知识库助手（摘要已填）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>增量组件</th><th>层</th><th>对外协议变化</th></tr></thead><tbody><tr><td><code>knowledge</code> 上传与 Ingestion Job</td><td>应用 + 数据</td><td>新增文档 API；Chat 仍 Thread/Run</td></tr><tr><td><code>retrieval</code> + pgvector</td><td>数据 + 基础设施</td><td>Run 内检索；SSE 可增 <code>citation</code> 事件</td></tr><tr><td>引用卡 UI</td><td>交互</td><td>只读投影 citation</td></tr></tbody></table><p>评测与权限交付见 <a href="/ts-ai/architecture/delivery/evaluation-plan">评测方案</a>、<a href="/ts-ai/architecture/delivery/data-permission-design">数据与权限设计</a>。</p><h2 id="_3-字段说明" tabindex="-1">3. 字段说明 <a class="header-anchor" href="#_3-字段说明" aria-label="Permalink to &quot;3. 字段说明&quot;">​</a></h2><h3 id="_3-1-各区块要什么证据" tabindex="-1">3.1 各区块要什么证据 <a class="header-anchor" href="#_3-1-各区块要什么证据" aria-label="Permalink to &quot;3.1 各区块要什么证据&quot;">​</a></h3><table tabindex="0"><thead><tr><th>区块</th><th>必须有</th><th>合格证据</th></tr></thead><tbody><tr><td>身份卡</td><td>版本、非目标、关联交付链接</td><td>与仓库 Manifest 一致</td></tr><tr><td>上下文图</td><td>外部系统与信任边界</td><td>可指到威胁模型入口</td></tr><tr><td>分层表</td><td>每层组件 + 非职责</td><td>无「前端调模型」类违规</td></tr><tr><td>数据流</td><td>至少 1 条主路径逐步表</td><td>与 OpenAPI / 事件名一致</td></tr><tr><td>状态所有权</td><td>权威写者一列无空</td><td>与目录模板不矛盾</td></tr><tr><td>质量属性</td><td>可测目标</td><td>链到评测或观测</td></tr></tbody></table><h3 id="_3-2-图例与文字一致性" tabindex="-1">3.2 图例与文字一致性 <a class="header-anchor" href="#_3-2-图例与文字一致性" aria-label="Permalink to &quot;3.2 图例与文字一致性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>检查</th><th>要求</th></tr></thead><tbody><tr><td>图中有、表中无</td><td>禁止；补组件行</td></tr><tr><td>表中有、代码无</td><td>标「计划」或删除</td></tr><tr><td>事件名</td><td>与 <code>packages/contracts</code> 一致</td></tr></tbody></table><h2 id="_4-常见漏填与验收失败" tabindex="-1">4. 常见漏填与验收失败 <a class="header-anchor" href="#_4-常见漏填与验收失败" aria-label="Permalink to &quot;4. 常见漏填与验收失败&quot;">​</a></h2><table tabindex="0"><thead><tr><th>漏填 / 错误</th><th>失败表现</th><th>修复</th></tr></thead><tbody><tr><td>只有六层空框</td><td>无法指导实现</td><td>填本项目组件名</td></tr><tr><td>未写非目标</td><td>范围蔓延</td><td>身份卡强制非目标</td></tr><tr><td>状态所有权缺失</td><td>刷新丢话 / 双 Run</td><td>补 §2.5</td></tr><tr><td>Gateway 画在浏览器</td><td>密钥泄漏风险</td><td>纠正依赖方向</td></tr><tr><td>知识库另起 WebSocket 协议</td><td>双栈无法验收</td><td>复用 Thread/Run + SSE</td></tr><tr><td>与威胁模型边界不一致</td><td>安全评审打回</td><td>同步上下文图</td></tr></tbody></table><h2 id="_5-关联章节" tabindex="-1">5. 关联章节 <a class="header-anchor" href="#_5-关联章节" aria-label="Permalink to &quot;5. 关联章节&quot;">​</a></h2><table tabindex="0"><thead><tr><th>章节</th><th>关系</th></tr></thead><tbody><tr><td><a href="/ts-ai/architecture/delivery/">项目交付总览</a></td><td>交付文档入口</td></tr><tr><td><a href="/ts-ai/architecture/delivery/requirements-acceptance">需求与验收标准</a></td><td>范围与 DoD</td></tr><tr><td><a href="/ts-ai/architecture/delivery/data-permission-design">数据与权限设计</a></td><td>数据对象细化</td></tr><tr><td><a href="/ts-ai/architecture/delivery/threat-model">威胁模型</a></td><td>同边界下的攻击路径</td></tr><tr><td><a href="/ts-ai/architecture/design-decisions/ts-ai-fullstack-architecture">TS-AI 全栈分层架构</a></td><td>六层方法</td></tr><tr><td><a href="/ts-ai/architecture/design-decisions/framework-boundaries">框架边界</a></td><td>Nuxt/Nest/LangChain</td></tr><tr><td><a href="/ts-ai/architecture/design-decisions/frontend-backend-state-ownership">前后端状态所有权</a></td><td>状态矩阵</td></tr><tr><td><a href="/ts-ai/architecture/design-decisions/model-gateway">Model Gateway</a></td><td>网关决策</td></tr><tr><td><a href="/ts-ai/architecture/ai-customer-support/">实战 · AI 客服中心</a></td><td>实际基线项目</td></tr><tr><td><a href="/ts-ai/quality/observability-reliability/structured-logging">结构化日志</a> / <a href="/ts-ai/quality/observability-reliability/traces-metrics">Traces 与指标</a></td><td>观测落点</td></tr><tr><td><a href="/ts-ai/appendix/templates/project-directory-template">项目目录模板</a></td><td>物理映射</td></tr><tr><td><a href="/ts-ai/appendix/templates/threat-model-template">威胁模型模板</a></td><td>安全填写</td></tr></tbody></table>`,37)])])}const u=d(s,[["render",n]]);export{b as __pageData,u as default};
